import { useCallback, useSyncExternalStore } from 'react';
import type { DiagramFlowPreset, DiagramType } from '../../services/diagrams/diagram_data';
import {
    diagramEditSessionService,
    type DiagramPersistentTool,
} from '../../services/diagrams/diagram_edit_session_service';
import {
    diagramNodePlacementService,
    type DiagramNodePlacementDefinition,
    type DiagramNodePlacementService,
} from '../../services/diagrams/diagram_node_placement_service';
import { DiagramToolboxButton } from './diagram_toolbox_button';
import { useActiveDiagramTool } from './use_diagram_tool';

const STEP_NODE_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New step', role: 'focal', width: 160 },
    kind: 'step',
};

export type DiagramStepNodeMetadataField = 'preset' | 'type';

export interface DiagramStepNodeSession {
    getActiveToolSnapshot: () => DiagramPersistentTool;
    getMetadataFieldSnapshot: {
        (field: 'preset'): DiagramFlowPreset | null;
        (field: 'type'): DiagramType | null;
    };
    subscribeActiveTool: (listener: () => void) => () => void;
    subscribeMetadataField: (field: DiagramStepNodeMetadataField, listener: () => void) => () => void;
    subscribeSession: (listener: () => void) => () => void;
}

export type DiagramStepNodePlacement = Pick<DiagramNodePlacementService, 'activate'>;

interface DiagramStepNodeButtonProps {
    placement?: DiagramStepNodePlacement;
    session?: DiagramStepNodeSession;
}

function useFlowchartAvailability(session: DiagramStepNodeSession) {
    const subscribe = useCallback((listener: () => void) => {
        const unsubscribePreset = session.subscribeMetadataField('preset', listener);
        const unsubscribeType = session.subscribeMetadataField('type', listener);
        const unsubscribeSession = session.subscribeSession(listener);

        return () => {
            unsubscribePreset();
            unsubscribeType();
            unsubscribeSession();
        };
    }, [session]);
    const getSnapshot = useCallback(
        () => session.getMetadataFieldSnapshot('type') === 'flow' && session.getMetadataFieldSnapshot('preset') === 'flowchart',
        [session],
    );

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

/** Activates step placement only for flow diagrams whose flowchart preset permits step nodes. */
export function DiagramStepNodeButton({
    placement = diagramNodePlacementService,
    session = diagramEditSessionService,
}: DiagramStepNodeButtonProps) {
    const available = useFlowchartAvailability(session);
    const activeTool = useActiveDiagramTool(session);
    const handleActivate = useCallback(() => {
        placement.activate(STEP_NODE_DEFINITION);
    }, [placement]);

    if (!available) return null;

    return (
        <DiagramToolboxButton
            active={activeTool === 'node:step'}
            label="Step"
            onActivate={handleActivate}
            tooltip="Place step node"
        />
    );
}

import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, describe, expect, it, vi } from 'vitest';
import type { DiagramFlowPreset, DiagramType } from '../../services/diagrams/diagram_data';
import type { DiagramPersistentTool } from '../../services/diagrams/diagram_edit_session_service';
import {
    DiagramStepNodeButton,
    type DiagramStepNodeMetadataField,
    type DiagramStepNodePlacement,
    type DiagramStepNodeSession,
} from './diagram_step_node_button';

class StepNodeSessionStub extends EventTarget {
    private activeTool: DiagramPersistentTool = 'select';
    private readonly diagramType: DiagramType;
    private readonly flowPreset: DiagramFlowPreset | null;

    constructor(diagramType: DiagramType, flowPreset: DiagramFlowPreset | null = null) {
        super();
        this.diagramType = diagramType;
        this.flowPreset = flowPreset;
    }

    readonly getActiveToolSnapshot = () => this.activeTool;
    readonly getMetadataFieldSnapshot = ((field: DiagramStepNodeMetadataField) => (
        field === 'preset' ? this.flowPreset : this.diagramType
    )) as DiagramStepNodeSession['getMetadataFieldSnapshot'];
    readonly subscribeActiveTool = (listener: () => void) => {
        this.addEventListener('activeToolChanged', listener);

        return () => this.removeEventListener('activeToolChanged', listener);
    };
    readonly subscribeMetadataField = vi.fn((field: DiagramStepNodeMetadataField, listener: () => void) => {
        this.addEventListener(`${field}Changed`, listener);

        return () => this.removeEventListener(`${field}Changed`, listener);
    });
    readonly subscribeSession = (listener: () => void) => {
        this.addEventListener('sessionChanged', listener);

        return () => this.removeEventListener('sessionChanged', listener);
    };

    setActiveTool(activeTool: DiagramPersistentTool) {
        this.activeTool = activeTool;
        this.dispatchEvent(new Event('activeToolChanged'));
    }
}

afterEach(cleanup);

describe('DiagramStepNodeButton', () => {
    it('activates step defaults for flowchart diagrams and observes only type and preset availability', () => {
        const session = new StepNodeSessionStub('flow', 'flowchart');
        const placement: DiagramStepNodePlacement = { activate: vi.fn(() => true) };
        render(<DiagramStepNodeButton placement={placement} session={session} />);
        const button = screen.getByRole('button', { name: 'Step' });

        expect(button).toHaveAttribute('aria-pressed', 'false');
        fireEvent.click(button);

        expect(placement.activate).toHaveBeenCalledWith({
            defaults: { height: 72, label: 'New step', role: 'focal', width: 160 },
            kind: 'step',
        });
        expect(session.subscribeMetadataField.mock.calls.every(
            ([field]) => field === 'preset' || field === 'type',
        )).toBe(true);

        act(() => { session.setActiveTool('node:step'); });
        expect(button).toHaveAttribute('aria-pressed', 'true');
    });

    it('is absent for flow diagrams using the state preset', () => {
        render(
            <DiagramStepNodeButton
                placement={{ activate: vi.fn(() => true) }}
                session={new StepNodeSessionStub('flow', 'state')}
            />,
        );

        expect(screen.queryByRole('button', { name: 'Step' })).not.toBeInTheDocument();
    });

    it.each(['architecture', 'dependency', 'sequence', 'entity'] as const)(
        'is absent for %s diagrams',
        (diagramType) => {
            render(
                <DiagramStepNodeButton
                    placement={{ activate: vi.fn(() => true) }}
                    session={new StepNodeSessionStub(diagramType)}
                />,
            );

            expect(screen.queryByRole('button', { name: 'Step' })).not.toBeInTheDocument();
        },
    );
});

import { useCallback, useSyncExternalStore } from 'react';
import type { DiagramType } from '../../services/diagrams/diagram_data';
import {
    diagramEditSessionService,
    type DiagramPersistentTool,
} from '../../services/diagrams/diagram_edit_session_service';
import {
    diagramNodePlacementService,
    type DiagramNodePlacementDefinition,
    type DiagramNodePlacementService,
} from '../../services/diagrams/diagram_node_placement_service';
import { DiagramToolboxButton } from './diagram_toolbox_button';
import { useActiveDiagramTool } from './use_diagram_tool';

const PARTICIPANT_DEFAULT_HEIGHT = 72;
const PARTICIPANT_DEFAULT_WIDTH = 160;
const PARTICIPANT_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: {
        height: PARTICIPANT_DEFAULT_HEIGHT,
        label: 'New participant',
        role: 'focal',
        width: PARTICIPANT_DEFAULT_WIDTH,
    },
    kind: 'participant',
};

export interface DiagramParticipantButtonSession {
    getActiveToolSnapshot: () => DiagramPersistentTool;
    getMetadataFieldSnapshot: (field: 'type') => DiagramType | null;
    subscribeActiveTool: (listener: () => void) => () => void;
    subscribeMetadataField: (field: 'type', listener: () => void) => () => void;
    subscribeSession: (listener: () => void) => () => void;
}

interface DiagramParticipantButtonProps {
    placement?: Pick<DiagramNodePlacementService, 'activate'>;
    session?: DiagramParticipantButtonSession;
}

/** Sequence-only participant placement tool bound to diagram type and active tool state. */
export function DiagramParticipantButton({
    placement = diagramNodePlacementService,
    session = diagramEditSessionService,
}: DiagramParticipantButtonProps) {
    const subscribeDiagramType = useCallback((listener: () => void) => {
        const unsubscribeMetadata = session.subscribeMetadataField('type', listener);
        const unsubscribeSession = session.subscribeSession(listener);

        return () => {
            unsubscribeMetadata();
            unsubscribeSession();
        };
    }, [session]);
    const getDiagramType = useCallback(() => session.getMetadataFieldSnapshot('type'), [session]);
    const diagramType = useSyncExternalStore(subscribeDiagramType, getDiagramType, getDiagramType);
    const activeTool = useActiveDiagramTool(session);
    const handleActivate = useCallback(() => {
        placement.activate(PARTICIPANT_DEFINITION);
    }, [placement]);

    if (diagramType !== 'sequence') return null;

    return (
        <DiagramToolboxButton
            active={activeTool === 'node:participant'}
            label="Participant"
            onActivate={handleActivate}
            tooltip="Place participant"
        />
    );
}

import { Box, Tab, Tabs, Tooltip, Typography } from '@mui/material';
import {
    useCallback, useId, useState, useSyncExternalStore,
    type SyntheticEvent,
} from 'react';
import {
    diagramEditSessionService,
    type DiagramPersistentTool,
    type DiagramToolboxSection,
} from '../../services/diagrams/diagram_edit_session_service';
import {
    diagramNodePlacementService,
} from '../../services/diagrams/diagram_node_placement_service';
import { ResizablePopper } from '../resizable_popper';
import {
    DiagramComponentNodeButton,
    type DiagramComponentNodePlacement,
    type DiagramComponentNodeSession,
} from './diagram_component_node_button';
import { DiagramCopyButton } from './diagram_copy_button';
import { DiagramCutButton } from './diagram_cut_button';
import { DiagramDeleteButton } from './diagram_delete_button';
import { DiagramPasteButton } from './diagram_paste_button';
import {
    DiagramParticipantButton,
} from './diagram_participant_button';
import {
    DiagramStepNodeButton,
    type DiagramStepNodePlacement,
    type DiagramStepNodeSession,
} from './diagram_step_node_button';
import { DiagramToolboxToolButton } from './diagram_toolbox_tool_button';
import { DiagramZoomInButton } from './diagram_zoom_in_button';
import { DiagramZoomOutButton } from './diagram_zoom_out_button';
import { useCancelDiagramInteractionOnEscape } from './use_diagram_tool';

const DIAGRAM_TOOLBOX_SIZE_STORAGE_KEY = 'md2.diagramToolboxSize';
const TOOLBOX_SECTIONS: readonly { id: DiagramToolboxSection, label: string }[] = [
    { id: 'edit', label: 'Edit' },
    { id: 'nodes', label: 'Nodes' },
    { id: 'edges', label: 'Edges' },
    { id: 'groups', label: 'Groups' },
    { id: 'others', label: 'Others' },
];
const INITIAL_TOOLBOX_SIZE = { height: 200, width: 360 };
const MINIMUM_TOOLBOX_SIZE = { height: 120, width: 280 };

interface DiagramToolboxProps {
    boundaryElement: HTMLElement | null;
    placement?: DiagramComponentNodePlacement & DiagramStepNodePlacement;
    session?: Omit<DiagramComponentNodeSession, 'getMetadataFieldSnapshot' | 'subscribeMetadataField'>
    & DiagramStepNodeSession & {
        getActiveToolboxSectionSnapshot: () => DiagramToolboxSection;
        getActiveToolSnapshot: () => DiagramPersistentTool;
        getViewportScaleSnapshot: () => number;
        cancelActiveInteraction: () => boolean;
        setActiveTool: (tool: DiagramPersistentTool) => void;
        setActiveToolboxSection: (section: DiagramToolboxSection) => void;
        subscribeActiveTool: (listener: () => void) => () => void;
        subscribeActiveToolboxSection: (listener: () => void) => () => void;
        subscribeViewportScale: (listener: () => void) => () => void;
        zoomIn: () => boolean;
        zoomOut: () => boolean;
    };
}

/** Floating shell for diagram tools. Tool leaves are added by their focused feature jobs. */
export function DiagramToolbox({
    boundaryElement,
    placement = diagramNodePlacementService,
    session = diagramEditSessionService,
}: DiagramToolboxProps) {
    const [anchorElement, setAnchorElement] = useState<HTMLDivElement | null>(null);
    const titleId = useId();
    useCancelDiagramInteractionOnEscape(session);
    const activeSection = useSyncExternalStore(
        session.subscribeActiveToolboxSection,
        session.getActiveToolboxSectionSnapshot,
        session.getActiveToolboxSectionSnapshot,
    );
    const handleSectionChange = useCallback((_event: SyntheticEvent, section: DiagramToolboxSection) => {
        session.setActiveToolboxSection(section);
    }, [session]);

    return (
        <>
            <Box
                aria-hidden="true"
                ref={setAnchorElement}
                sx={{ height: 0, position: 'absolute', right: 2, top: 5, width: 0 }}
            />
            <ResizablePopper
                anchorElement={anchorElement}
                boundaryElement={boundaryElement}
                closeOnEscape={false}
                focusOnMount={false}
                initialSize={INITIAL_TOOLBOX_SIZE}
                labelId={titleId}
                minimumSize={MINIMUM_TOOLBOX_SIZE}
                open={!!anchorElement && !!boundaryElement}
                paperSx={{
                    bgcolor: 'background.paper',
                    border: 1,
                    borderColor: 'divider',
                    borderRadius: 1.75,
                    boxShadow: 8,
                    flexDirection: 'column',
                }}
                placement="bottom-end"
                resizeFromAllSides
                resizeLabel="Resize diagram toolbox"
                storageKey={DIAGRAM_TOOLBOX_SIZE_STORAGE_KEY}
            >
                <Typography id={titleId} sx={{ px: 1.5, pt: 1.25 }} variant="subtitle2">
                    Diagram tools
                </Typography>
                <Tabs
                    aria-label="Diagram tool sections"
                    onChange={handleSectionChange}
                    scrollButtons="auto"
                    value={activeSection}
                    variant="scrollable"
                >
                    {TOOLBOX_SECTIONS.map(({ id, label }) => (
                        <Tab
                            aria-controls={`${titleId}-${id}-panel`}
                            id={`${titleId}-${id}-tab`}
                            key={id}
                            label={<Tooltip title={label}><Box component="span">{label}</Box></Tooltip>}
                            value={id}
                        />
                    ))}
                </Tabs>
                <Box
                    aria-labelledby={`${titleId}-${activeSection}-tab`}
                    id={`${titleId}-${activeSection}-panel`}
                    role="tabpanel"
                    sx={{ alignContent: 'flex-start', display: 'flex', flex: 1, flexWrap: 'wrap', gap: 1, overflow: 'auto', p: 1.5 }}
                >
                    {activeSection === 'edit' && (
                        <>
                            <DiagramToolboxToolButton
                                label="Select"
                                session={session}
                                tool="select"
                                tooltip="Select diagram objects"
                            />
                            <DiagramZoomInButton session={session} />
                            <DiagramZoomOutButton session={session} />
                            <DiagramCopyButton />
                            <DiagramPasteButton />
                            <DiagramCutButton />
                            <DiagramDeleteButton />
                        </>
                    )}
                    {activeSection === 'nodes' && (
                        <>
                            <DiagramComponentNodeButton placement={placement} session={session} />
                            <DiagramParticipantButton placement={placement} session={session} />
                            <DiagramStepNodeButton placement={placement} session={session} />
                        </>
                    )}
                </Box>
            </ResizablePopper>
        </>
    );
}

import { register } from '../service_injector'
import {
    requireDiagramNodeKind,
    type DiagramFlowPreset,
    type DiagramNode,
    type DiagramNodeKind,
    type DiagramType,
} from './diagram_data'
import {
    diagramEditSessionService,
    type DiagramEditSessionService,
    type NewDiagramNode,
} from './diagram_edit_session_service'
import { DIAGRAM_GRID_SIZE, type PositionedDiagramNode } from './diagram_layout'
import {
    diagramSelectionService,
    type DiagramSelectionService,
} from './diagram_selection_service'

const PREVIEW_CHANGED_EVENT = 'nodePlacement:preview'
const PREVIEW_NODE_ID = 'node-placement-preview'

export interface DiagramNodePlacementPoint {
    x: number
    y: number
}

export type DiagramNodePlacementDefaults = Omit<NewDiagramNode, 'height' | 'kind' | 'width' | 'x' | 'y'> & {
    height: number
    width: number
}

export interface DiagramNodePlacementDefinition {
    defaults: DiagramNodePlacementDefaults
    kind: DiagramNodeKind
}

export interface DiagramNodePlacementPreview {
    diagramType: DiagramType
    flowPreset?: DiagramFlowPreset
    node: PositionedDiagramNode
}

function snapCoordinate(value: number) {
    return Math.round(value / DIAGRAM_GRID_SIZE) * DIAGRAM_GRID_SIZE
}

function requireFinitePoint(point: DiagramNodePlacementPoint) {
    if (!Number.isFinite(point.x) || !Number.isFinite(point.y)) {
        throw new Error('Diagram node placement point must be finite')
    }
}

function cloneDefaults(defaults: DiagramNodePlacementDefaults): DiagramNodePlacementDefaults {
    return {
        ...defaults,
        ...(defaults.fields ? { fields: defaults.fields.map((field) => ({ ...field })) } : {}),
    }
}

function samePreviewPoint(preview: DiagramNodePlacementPreview | null, x: number, y: number) {
    return preview?.node.x === x && preview.node.y === y
}

/** Owns one node tool from activation through transient preview and one committed placement. */
export class DiagramNodePlacementService extends EventTarget {
    private definition: DiagramNodePlacementDefinition | null = null
    private preview: DiagramNodePlacementPreview | null = null
    private readonly selection: Pick<DiagramSelectionService, 'replace'>
    private readonly session: DiagramEditSessionService

    constructor(
        session: DiagramEditSessionService = diagramEditSessionService,
        selection: Pick<DiagramSelectionService, 'replace'> = diagramSelectionService,
    ) {
        super()
        this.selection = selection
        this.session = session
        this.session.subscribeActiveTool(this.handleActiveToolChanged)
        this.session.subscribeSession(this.handleSessionChanged)
    }

    getPreviewSnapshot = () => this.preview

    subscribePreview = (listener: () => void) => {
        this.addEventListener(PREVIEW_CHANGED_EVENT, listener)

        return () => this.removeEventListener(PREVIEW_CHANGED_EVENT, listener)
    }

    isNodeKindAvailable(kind: DiagramNodeKind) {
        if (!this.session.getSessionSnapshot()) return false

        const diagramType = this.session.getMetadataFieldSnapshot('type')
        const flowPreset = this.session.getMetadataFieldSnapshot('preset')
        if (!diagramType) return false

        try {
            requireDiagramNodeKind(kind, diagramType, flowPreset ?? undefined, 'node.kind')

            return true
        } catch {
            return false
        }
    }

    isPlacementActive() {
        return !!this.definition && this.session.getActiveToolSnapshot() === `node:${this.definition.kind}`
    }

    activate(definition: DiagramNodePlacementDefinition) {
        if (!this.session.getSessionSnapshot()) throw new Error('Cannot activate node placement without an active edit session')
        if (!this.isNodeKindAvailable(definition.kind)) return false

        this.definition = { defaults: cloneDefaults(definition.defaults), kind: definition.kind }
        this.setPreview(null)
        this.session.setActiveTool(`node:${definition.kind}`)

        return true
    }

    updatePreview(point: DiagramNodePlacementPoint) {
        requireFinitePoint(point)
        const definition = this.requireActiveDefinition()
        const diagramType = this.session.getMetadataFieldSnapshot('type')
        const flowPreset = this.session.getMetadataFieldSnapshot('preset')
        if (!diagramType) throw new Error('Cannot preview node placement without diagram metadata')

        const x = snapCoordinate(point.x)
        const y = snapCoordinate(point.y)
        if (samePreviewPoint(this.preview, x, y)) return false

        const modelNode: DiagramNode = { ...cloneDefaults(definition.defaults), id: PREVIEW_NODE_ID, kind: definition.kind, x, y }
        const { height, width } = definition.defaults
        const node: PositionedDiagramNode = { ...modelNode, fanIn: 0, height, width, x, y }
        const preview = {
            diagramType,
            ...(flowPreset ? { flowPreset } : {}),
            node,
        }
        this.setPreview(preview)
        this.session.beginTransientGesture('placement')

        return true
    }

    place(point: DiagramNodePlacementPoint) {
        this.updatePreview(point)
        const definition = this.requireActiveDefinition()
        const preview = this.preview
        if (!preview) throw new Error('Cannot place a diagram node without a preview')

        const node: NewDiagramNode = {
            ...cloneDefaults(definition.defaults),
            kind: definition.kind,
            x: preview.node.x,
            y: preview.node.y,
        }
        const nodeId = this.session.createNode(node)
        if (!nodeId) return null

        this.selection.replace([{ objectId: nodeId, objectKind: 'node' }])
        this.definition = null
        this.setPreview(null)
        this.session.setActiveTool('select')

        return nodeId
    }

    cancelPlacement() {
        if (!this.definition && !this.preview) return false

        this.definition = null
        this.setPreview(null)
        this.session.cancelActiveInteraction()

        return true
    }

    private readonly handleActiveToolChanged = () => {
        if (this.isPlacementActive()) return

        this.clearPlacement()
    }

    private readonly handleSessionChanged = () => this.clearPlacement()

    private clearPlacement() {
        this.definition = null
        this.setPreview(null)
    }

    private requireActiveDefinition() {
        if (!this.definition || !this.isPlacementActive()) throw new Error('No diagram node placement is active')

        return this.definition
    }

    private setPreview(preview: DiagramNodePlacementPreview | null) {
        if (preview === this.preview) return

        this.preview = preview
        this.dispatchEvent(new Event(PREVIEW_CHANGED_EVENT))
    }
}

export const diagramNodePlacementService = register(
    'diagramNodePlacementService',
    new DiagramNodePlacementService(),
)

import { memo } from 'react'
import type { DiagramEntityField } from '../../services/diagrams/diagram_data'
import {
    diagramEditSessionService, type DiagramEditSessionService,
} from '../../services/diagrams/diagram_edit_session_service'
import { diagramGeometryService, type DiagramGeometryService } from '../../services/diagrams/diagram_geometry_service'
import type { PositionedDiagramNode } from '../../services/diagrams/diagram_layout'
import {
    diagramSelectionService, type DiagramSelectionService,
} from '../../services/diagrams/diagram_selection_service'
import { DiagramNode } from './diagram_node'
import {
    diagramObjectDetailsService, type DiagramObjectDetailsService,
} from './diagram_object_details_service'
import { useDiagramNodeGeometryField } from './use_diagram_geometry'
import { useIsDiagramObjectSelected } from './use_diagram_selection'
import { useEditableDiagramMetadataField, useEditableDiagramNodeField } from './use_editable_diagram'

interface EditableDiagramNodeProps {
    details?: DiagramObjectDetailsService
    geometry?: DiagramGeometryService
    nodeId: string
    selection?: DiagramSelectionService
    session?: DiagramEditSessionService
}

/**
 * One node of the New diagram. Every value it renders arrives through its own field subscription, so an edit to a
 * sibling node, an edge, a group, or the metadata cannot rerender this leaf.
 */
function EditableDiagramNodeLeaf({
    details = diagramObjectDetailsService,
    geometry = diagramGeometryService,
    nodeId,
    selection = diagramSelectionService,
    session = diagramEditSessionService,
}: EditableDiagramNodeProps) {
    const diagramType = useEditableDiagramMetadataField('type', session)
    const preset = useEditableDiagramMetadataField('preset', session)
    const fields = useEditableDiagramNodeField(nodeId, 'fields', session)
    const kind = useEditableDiagramNodeField(nodeId, 'kind', session)
    const label = useEditableDiagramNodeField(nodeId, 'label', session)
    const role = useEditableDiagramNodeField(nodeId, 'role', session)
    const sublabel = useEditableDiagramNodeField(nodeId, 'sublabel', session)
    const tag = useEditableDiagramNodeField(nodeId, 'tag', session)
    const fanIn = useDiagramNodeGeometryField(nodeId, 'fanIn', geometry)
    const height = useDiagramNodeGeometryField(nodeId, 'height', geometry)
    const width = useDiagramNodeGeometryField(nodeId, 'width', geometry)
    const x = useDiagramNodeGeometryField(nodeId, 'x', geometry)
    const y = useDiagramNodeGeometryField(nodeId, 'y', geometry)
    const selected = useIsDiagramObjectSelected(nodeId, 'node', selection)
    if (!diagramType || label === null || role === null || width === null || height === null) return null

    const handleSelect = (_selection: unknown, ctrlKey: boolean) => {
        if (session.getActiveToolSnapshot() !== 'select') return

        const identity = { objectId: nodeId, objectKind: 'node' } as const
        if (ctrlKey) {
            selection.toggle(identity)
            return
        }
        selection.replace([identity])
    }
    const handleOpenDetails = () => details.open({ objectId: nodeId, objectKind: 'node' })

    const node: PositionedDiagramNode = {
        fanIn: fanIn ?? 0,
        height,
        id: nodeId,
        label,
        role,
        width,
        x: x ?? 0,
        y: y ?? 0,
        ...(fields ? { fields: fields as DiagramEntityField[] } : {}),
        ...(kind ? { kind } : {}),
        ...(sublabel ? { sublabel } : {}),
        ...(tag ? { tag } : {}),
    }

    return (
        <DiagramNode
            diagramType={diagramType}
            flowPreset={preset ?? undefined}
            node={node}
            onOpenDetails={handleOpenDetails}
            onSelect={handleSelect}
            selected={selected}
        />
    )
}

/** Memoised so a collection host rerender caused by another member cannot rerender this leaf. */
export const EditableDiagramNode = memo(EditableDiagramNodeLeaf)

import { useCallback, useSyncExternalStore } from 'react';
import type { DiagramFlowPreset, DiagramType } from '../../services/diagrams/diagram_data';
import {
    diagramEditSessionService,
    type DiagramPersistentTool,
} from '../../services/diagrams/diagram_edit_session_service';
import {
    diagramNodePlacementService,
    type DiagramNodePlacementDefinition,
    type DiagramNodePlacementService,
} from '../../services/diagrams/diagram_node_placement_service';
import { DiagramToolboxButton } from './diagram_toolbox_button';
import { useActiveDiagramTool } from './use_diagram_tool';

const STEP_NODE_DEFINITION: DiagramNodePlacementDefinition = {
    defaults: { height: 72, label: 'New step', role: 'focal', width: 160 },
    kind: 'step',
};

export type DiagramStepNodeMetadataField = 'preset' | 'type';

export interface DiagramStepNodeSession {
    getActiveToolSnapshot: () => DiagramPersistentTool;
    getMetadataFieldSnapshot: {
        (field: 'preset'): DiagramFlowPreset | null;
        (field: 'type'): DiagramType | null;
    };
    subscribeActiveTool: (listener: () => void) => () => void;
    subscribeMetadataField: (field: DiagramStepNodeMetadataField, listener: () => void) => () => void;
    subscribeSession: (listener: () => void) => () => void;
}

export type DiagramStepNodePlacement = Pick<DiagramNodePlacementService, 'activate'>;

interface DiagramStepNodeButtonProps {
    placement?: DiagramStepNodePlacement;
    session?: DiagramStepNodeSession;
}

function useFlowchartAvailability(session: DiagramStepNodeSession) {
    const subscribe = useCallback((listener: () => void) => {
        const unsubscribePreset = session.subscribeMetadataField('preset', listener);
        const unsubscribeType = session.subscribeMetadataField('type', listener);
        const unsubscribeSession = session.subscribeSession(listener);

        return () => {
            unsubscribePreset();
            unsubscribeType();
            unsubscribeSession();
        };
    }, [session]);
    const getSnapshot = useCallback(
        () => session.getMetadataFieldSnapshot('type') === 'flow' && session.getMetadataFieldSnapshot('preset') === 'flowchart',
        [session],
    );

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

/** Activates step placement only for flow diagrams whose flowchart preset permits step nodes. */
export function DiagramStepNodeButton({
    placement = diagramNodePlacementService,
    session = diagramEditSessionService,
}: DiagramStepNodeButtonProps) {
    const available = useFlowchartAvailability(session);
    const activeTool = useActiveDiagramTool(session);
    const handleActivate = useCallback(() => {
        placement.activate(STEP_NODE_DEFINITION);
    }, [placement]);

    if (!available) return null;

    return (
        <DiagramToolboxButton
            active={activeTool === 'node:step'}
            label="Step"
            onActivate={handleActivate}
            tooltip="Place step node"
        />
    );
}

import { Box, ButtonBase, Typography } from '@mui/material'
import { useRef, type KeyboardEvent, type MouseEvent } from 'react'
import type { DiagramFlowPreset, DiagramType } from '../../services/diagrams/diagram_data'
import type { PositionedDiagramNode } from '../../services/diagrams/diagram_layout'
import { diagramRoleStyle } from './diagram_role_style'
import type { DiagramSelectHandler } from './diagram_selection'

interface DiagramNodeProps {
    diagramType: DiagramType
    flowPreset?: DiagramFlowPreset
    node: PositionedDiagramNode
    onOpenDetails?: () => void
    onSelect: DiagramSelectHandler
    selected: boolean
}

function kindStyles(node: PositionedDiagramNode, flowPreset: DiagramFlowPreset | undefined) {
    if (flowPreset === 'state' && node.kind === 'start') {
        return {bgcolor: 'text.primary', border: 0, borderRadius: 99} as const
    }
    if (flowPreset === 'state' && node.kind === 'end') {
        return {
            bgcolor: 'background.default', border: '2px solid', borderColor: 'text.primary', borderRadius: 99,
            '&::before': {
                bgcolor: 'text.primary', borderRadius: 99, content: '""', height: 10, left: 5,
                position: 'absolute', top: 5, width: 10,
            },
        } as const
    }
    if (node.kind === 'start' || node.kind === 'end') return { borderRadius: 99 }
    if (node.kind === 'decision') return { transform: 'rotate(45deg)', '& > *': { transform: 'rotate(-45deg)' } }

    return { borderRadius: node.kind === 'state' ? 1 : '6px' }
}

function fieldPrefix(key: 'primary' | 'foreign' | undefined) {
    if (key === 'primary') return '# '
    if (key === 'foreign') return 'â†’ '

    return ''
}

/** Positioned, themed, keyboard-operable diagram item. */
export function DiagramNode({ diagramType, flowPreset, node, onOpenDetails, onSelect, selected }: DiagramNodeProps) {
    const stateMarker = flowPreset === 'state' && (node.kind === 'start' || node.kind === 'end')
    const interactive = node.drilldown !== false || !!onOpenDetails
    const scrollRef = useRef<HTMLDivElement>(null)
    const pressScrollTop = useRef(0)
    const handleSelect = (left: number, top: number, ctrlKey: boolean) => (
        onSelect({ id: node.id, label: node.label, left, top }, ctrlKey)
    )
    const handleMouseDown = () => { pressScrollTop.current = scrollRef.current?.scrollTop ?? 0 }
    const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
        // A scrollbar drag inside the content area presses and releases on the button; that is a scroll, not a selection.
        if ((scrollRef.current?.scrollTop ?? 0) !== pressScrollTop.current) return
        handleSelect(event.clientX, event.clientY, event.ctrlKey)
    }
    const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
        if (event.key !== 'Enter' && event.key !== ' ') return
        event.preventDefault()
        const bounds = event.currentTarget.getBoundingClientRect()
        handleSelect(bounds.left, bounds.bottom, false)
    }
    const handleDoubleClick = (event: MouseEvent<HTMLButtonElement>) => {
        if (!onOpenDetails) return

        event.preventDefault()
        event.stopPropagation()
        onOpenDetails()
    }

    return (
        <ButtonBase
            aria-label={node.label}
            aria-disabled={interactive ? undefined : true}
            aria-pressed={interactive ? selected : undefined}
            data-diagram-id={node.id}
            data-diagram-kind="node"
            onClick={interactive ? handleClick : undefined}
            onDoubleClick={onOpenDetails ? handleDoubleClick : undefined}
            onKeyDown={interactive ? handleKeyDown : undefined}
            onMouseDown={interactive ? handleMouseDown : undefined}
            role="button"
            sx={{
                alignItems: 'stretch', border: '1px solid', color: 'text.primary', display: 'flex', flexDirection: 'column',
                height: node.height, left: node.x, overflow: 'hidden', position: 'absolute', textAlign: 'left',
                top: node.y, width: node.width, zIndex: 2,
                ...diagramRoleStyle(node.role),
                ...kindStyles(node, flowPreset),
                ...(selected ? { outline: '2px solid', outlineColor: 'primary.main', outlineOffset: 2 } : {}),
                '&:focus-visible': { borderColor: 'primary.main', outline: '2px solid', outlineColor: 'primary.main', outlineOffset: 2 },
            }}
            tabIndex={interactive ? undefined : -1}
        >
            {!stateMarker ? (
                <Box
                    data-diagram-scroll="content"
                    ref={scrollRef}
                    sx={{
                        display: 'flex', flex: 1, flexDirection: 'column',
                        // `safe center` centres content that fits and falls back to top alignment once it overflows,
                        // so the tag and label stay reachable instead of being clipped above the scroll origin.
                        justifyContent: 'safe center', minHeight: 0, overflowX: 'hidden', overflowY: 'auto',
                    }}
                >
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5, px: 2, py: 1 }}>
                        {node.tag ? <Typography color="custom.text3" variant="overline">{node.tag}</Typography> : null}
                        <Typography sx={{ fontWeight: 600, overflowWrap: 'anywhere' }} variant="body2">{node.label}</Typography>
                        {node.sublabel ? (
                            <Typography color="text.secondary" sx={{ overflowWrap: 'anywhere' }} variant="caption">{node.sublabel}</Typography>
                        ) : null}
                    </Box>
                    {diagramType === 'entity' && node.fields ? (
                        <Box sx={{ borderColor: 'divider', borderTop: '1px solid', display: 'flex', flexDirection: 'column', px: 2, py: 1 }}>
                            {node.fields.map((field) => (
                                <Typography key={`${field.key ?? 'field'}:${field.name}`} sx={{ fontFamily: 'monospace' }} variant="caption">
                                    {fieldPrefix(field.key)}{field.name}{field.type ? `: ${field.type}` : ''}
                                </Typography>
                            ))}
                        </Box>
                    ) : null}
                </Box>
            ) : null}
            {diagramType === 'dependency' ? (
                <Typography
                    color="text.secondary"
                    sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 0.25, position: 'absolute', px: 0.5, right: 1, top: 0.75 }}
                    variant="caption"
                >
                    {node.fanIn} in
                </Typography>
            ) : null}
        </ButtonBase>
    )
}

import { ThemeProvider } from '@mui/material'
import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { DiagramFlowPreset, DiagramType } from '../../services/diagrams/diagram_data'
import type { PositionedDiagramNode } from '../../services/diagrams/diagram_layout'
import { createAppTheme } from '../../theme/app_theme'
import { DiagramNode } from './diagram_node'

function positioned(overrides: Partial<PositionedDiagramNode> = {}): PositionedDiagramNode {
    // Cast: exactOptionalPropertyTypes rejects spreading a Partial whose optional members may be explicitly undefined.
    return { fanIn: 0, height: 72, id: 'one', label: 'One', width: 160, x: 0, y: 0, ...overrides } as PositionedDiagramNode
}

function renderNode(node: PositionedDiagramNode, diagramType: DiagramType = 'architecture', flowPreset?: DiagramFlowPreset) {
    const onSelect = vi.fn()
    render(
        <ThemeProvider theme={createAppTheme('dark')}>
            <DiagramNode diagramType={diagramType} flowPreset={flowPreset} node={node} onSelect={onSelect} selected={false} />
        </ThemeProvider>,
    )

    return { button: screen.getByRole('button', { name: node.label }), onSelect }
}

function scrollWrapper(button: HTMLElement) {
    return button.querySelector('[data-diagram-scroll="content"]') as HTMLElement | null
}

describe('DiagramNode', () => {
    afterEach(cleanup)

    it('puts tag, label and sublabel in a scrollable wrapper that only anchors to the top when content overflows', () => {
        const { button } = renderNode(positioned({ sublabel: 'a very long sublabel that does not fit', tag: 'service' }))
        const wrapper = scrollWrapper(button)

        expect(wrapper).not.toBeNull()
        expect(getComputedStyle(wrapper as HTMLElement).overflowY).toBe('auto')
        expect(getComputedStyle(wrapper as HTMLElement).justifyContent).toBe('safe center')
        expect(getComputedStyle(wrapper as HTMLElement).minHeight).toBe('0px')
        expect(wrapper).toContainElement(screen.getByText('service'))
        expect(wrapper).toContainElement(screen.getByText('One'))
        expect(wrapper).toContainElement(screen.getByText('a very long sublabel that does not fit'))
    })

    it('wraps a single unbroken token in the label and sublabel instead of clipping it', () => {
        renderNode(positioned({ label: 'src/services/diagrams/diagram_layout.ts', sublabel: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' }))

        expect(getComputedStyle(screen.getByText('src/services/diagrams/diagram_layout.ts')).overflowWrap).toBe('anywhere')
        expect(getComputedStyle(screen.getByText('aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa')).overflowWrap).toBe('anywhere')
    })

    it('keeps the fanIn badge outside the scroll wrapper so it does not scroll away', () => {
        const { button } = renderNode(positioned({ fanIn: 3 }), 'dependency')

        expect(scrollWrapper(button)).not.toContainElement(screen.getByText('3 in'))
        expect(button).toContainElement(screen.getByText('3 in'))
    })

    it('keeps the entity divider and field list inside the same scroll wrapper as the header', () => {
        const node = positioned({ fields: [{ key: 'primary' as const, name: 'id', type: 'UUID' }], height: 120 })
        const { button } = renderNode(node, 'entity')
        const fields = screen.getByText('# id: UUID').parentElement as HTMLElement

        expect(scrollWrapper(button)).toContainElement(fields)
        expect(getComputedStyle(fields).borderTop).toContain('1px solid')
    })

    it('renders no text and no scroll wrapper for state preset start and end markers', () => {
        const { button } = renderNode(positioned({ height: 24, kind: 'start', label: 'Start', width: 24 }), 'flow', 'state')

        expect(scrollWrapper(button)).toBeNull()
        expect(button).toBeEmptyDOMElement()
    })

    it('honours an explicit height from the diagram JSON', () => {
        const { button } = renderNode(positioned({ height: 200 }))

        expect(getComputedStyle(button).height).toBe('200px')
    })

    it('reports Ctrl state for clicks and treats keyboard activation as plain selection', async () => {
        const { button, onSelect } = renderNode(positioned())
        const user = userEvent.setup()

        await user.click(button)
        expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ id: 'one', label: 'One' }), false)

        onSelect.mockClear()
        fireEvent.click(button, { ctrlKey: true })
        expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ id: 'one', label: 'One' }), true)

        onSelect.mockClear()
        button.focus()
        await user.keyboard('{Enter}')
        expect(onSelect).toHaveBeenCalledWith(expect.objectContaining({ id: 'one', label: 'One' }), false)
    })

    it('does not select the node when the content scrolled between mousedown and click', () => {
        const { button, onSelect } = renderNode(positioned({ sublabel: 'long enough to scroll' }))
        const wrapper = scrollWrapper(button) as HTMLElement

        fireEvent.mouseDown(button)
        wrapper.scrollTop = 24
        fireEvent.click(button)

        expect(onSelect).not.toHaveBeenCalled()
    })

    it('keeps non-drilldown node content scrollable without allowing selection', async () => {
        const { button, onSelect } = renderNode(positioned({ drilldown: false, sublabel: 'long enough to scroll' }))
        const wrapper = scrollWrapper(button) as HTMLElement
        const user = userEvent.setup()

        expect(button).toHaveAttribute('aria-disabled', 'true')
        expect(button).toHaveAttribute('tabindex', '-1')
        expect(button).not.toBeDisabled()
        expect(getComputedStyle(wrapper).overflowY).toBe('auto')

        await user.click(wrapper)
        fireEvent.keyDown(button, { key: 'Enter' })

        expect(onSelect).not.toHaveBeenCalled()
    })
})

